"""kb.py — 知识库检索的统一入口（优先常驻服务，自动回退）。

为什么有这一层
--------------
`kb_search.py` 每次调用都要**重新加载 jieba 词典（0.53 s）**；语义检索还要
重新 `import sentence_transformers`（8.3 s）+ 加载模型（12.9 s）。
实测 CLI 语义检索 **30.2 s/次**、混合检索 **56.0 s/次**。

`kb_serve.py` 常驻进程把索引与模型只加载一次，之后每次查询毫秒级。
本客户端就是它的薄壳：**服务在就用服务；服务不在就退回进程内**，
两种路径返回同构结果，Agent 不必关心走的是哪条。

用法
----
    python tools/kb.py "固态电解质界面"                  # BM25（默认）
    python tools/kb.py "锂沉积效率" --mode hybrid -k 8
    python tools/kb.py "SSE" --resolve
    python tools/kb.py --stats
    python tools/kb.py --doctor                          # 自检 + 环境诊断
    python tools/kb.py "..." --json                      # 机器可读（Agent 用）
"""

import os
import sys
import json
import time
import argparse
import urllib.parse

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K
import kb_serve as S


def call(path, port, fallback, timeout=60):
    """优先走常驻服务；不可用时执行 fallback()。返回 (数据, 来源标记)。"""
    try:
        return S.request(path, port=port, timeout=timeout), "server"
    except Exception:                            # noqa: BLE001
        return fallback(), "in-process"


def _fallback_search(q, k, type_filter, mode):
    import kb_search as KS
    if mode in ("semantic", "hybrid"):
        import kb_semantic_search as SEM
        raw = (SEM.semantic_search(q, top_k=k * 3) if mode == "semantic"
               else SEM.hybrid_search(q, top_k=k * 3))
        meta, _ = KS.load_index()
        out = []
        for name, score in raw:
            s, u, tags, al, t = KS.meta_of(meta, name)
            if type_filter and t not in type_filter:
                continue
            out.append({"name": name, "type": t, "score": round(score, 4),
                        "summary": s, "updated": u, "tags": tags,
                        "aliases": al, "path": KS.page_path(name, t)})
        return {"mode": mode, "query": q, "count": len(out[:k]),
                "results": out[:k]}
    meta, bm = KS.load_index()
    alias_hits = KS.resolve_aliases(q, meta.get("alias_map", {}))
    strong = [(a, c) for a, c in alias_hits if len(a) >= 3] or alias_hits[:1]
    canon = [c for _, c in strong]
    qt = K.tokenize(q)
    for c in canon:
        qt.extend(K.tokenize(c))
    for a, c in alias_hits:
        if c not in canon:
            qt.extend(K.tokenize(c))
    ranked = KS.bm25_score(qt, bm, canon, query_raw=q)
    out = []
    for name, score in ranked:
        s, u, tags, al, t = KS.meta_of(meta, name)
        if type_filter and t not in type_filter:
            continue
        out.append({"name": name, "type": t, "score": round(score, 4),
                    "summary": s, "updated": u, "tags": tags,
                    "aliases": al, "path": KS.page_path(name, t)})
    return {"mode": "bm25", "query": q, "count": len(out[:k]),
            "results": out[:k]}


def _fallback_resolve(q):
    import kb_search as KS
    meta, _ = KS.load_index()
    return {"query": q,
            "alias_hits": KS.resolve_aliases(q, meta.get("alias_map", {}))}


def _fallback_stats():
    import kb_search as KS
    meta, bm = KS.load_index()
    return {"pages": meta.get("count"),
            "alias_entries": len(meta.get("alias_map", {})),
            "vocab": len(bm.get("df", {})), "n_docs": bm.get("n_docs"),
            "bm25_version": bm.get("_version", 1)}


# 参数解析走 kb_lib 的**单一实现**（此前在 kb.py / kb_route.py / kb_serve.py 各有一份）。
# 保留这两个名字只为向后兼容与可读性，实现不再分叉。
def _parse_budget(s):
    """`"5,5,8"` → `{"L1":5,"L2":5,"L3":8}`；空串 → None。"""
    return K.parse_budget(s)


def _parse_layers(s):
    """`"1,2"` → `(1,2)`；空串 → `(1,2,3)`（三层全跑）。"""
    return K.parse_layers(s)


def _fallback_route(q, budget="", layer=""):
    import kb_route as R
    return R.route(q, budget=_parse_budget(budget), layers=_parse_layers(layer))


def _fallback_corpus(q, k=8):
    import kb_corpus as C
    res = C.search(q, k=k)
    return {"mode": "corpus", "query": q, "count": len(res), "results": res}


def selftest():
    """底座自检（本文件此前**完全没有**自动门禁）。

    🔴 为什么补：`kb.py` 是 CLAUDE.md 写明的「**首选入口**」，但它没有下划线，
    因此**逃过了 `kb_*.py` glob** —— 既不在 `kb_toolcheck.py` 的名册里，
    也不在 `kb_lint_deep` E 族的扫描里。全库流量最大的工具成了唯一零门禁的一个。
    这里只做**不依赖索引内容**的不变量检查（索引是派生数据，缺/旧不算代码缺陷）：
      · 三个回退实现存在且可调用（进程内路径不被常驻服务绑架）
      · `--budget`/`--layer` 解析与 kb_route 的约定一致
      · 类型目录映射覆盖 kb_lib.PAGE_DIRS（漏一个类型，`--json` 的 path 就会 100% 不存在，
        这是本库真实发生过的事故）
    """
    import kb_lib as K
    import kb_search as KS
    ok = fail = 0

    def chk(name, cond):
        nonlocal ok, fail
        if cond:
            ok += 1
            print(f"  [ok  ] {name}")
        else:
            fail += 1
            print(f"  [FAIL] {name}")

    chk("三个回退实现都存在", all(callable(f) for f in
                                (_fallback_search, _fallback_route, _fallback_stats)))
    chk("--budget 解析成 L1/L2/L3 字典",
        _parse_budget("5,5,8") == {"L1": 5, "L2": 5, "L3": 8})
    chk("反例 空 --budget → None（不强行造预算）", _parse_budget("") is None)
    chk("--layer 解析成元组",
        _parse_layers("1,2") == (1, 2) and _parse_layers("") == (1, 2, 3))
    dirs = set(KS.TYPE_DIR.values())
    chk(f"TYPE_DIR 覆盖 PAGE_DIRS（{sorted(dirs)}）",
        dirs == set(K.PAGE_DIRS))
    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok + fail}")
    return 0 if fail == 0 else 1


def main():
    ap = argparse.ArgumentParser(description="知识库检索统一入口")
    ap.add_argument("query", nargs="?", default="")
    ap.add_argument("-k", type=int, default=10)
    ap.add_argument("--type", default="", help="逗号分隔：concept,entity,source,topic,output")
    ap.add_argument("--mode", default="bm25", choices=["bm25", "semantic", "hybrid"])
    ap.add_argument("--resolve", action="store_true")
    ap.add_argument("--route", action="store_true",
                    help="分层上下文包（L1 综合 / L2 文献卡 / L3 原文块）—— Agent 首选入口")
    ap.add_argument("--corpus", action="store_true", help="raw 全文分块检索（可回指行号）")
    ap.add_argument("--budget", default="", help="--route 用：L1,L2,L3 条数，如 5,5,8")
    ap.add_argument("--layer", default="", help="--route 用：只跑指定层，如 1 或 1,2")
    ap.add_argument("--stats", action="store_true")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--port", type=int, default=S.DEFAULT_PORT)
    ap.add_argument("--no-server", action="store_true", help="强制进程内执行")
    ap.add_argument("--doctor", action="store_true", help="环境与索引诊断")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()
    if args.doctor:
        return doctor(args.port)

    h = None if args.no_server else S.ping(args.port)
    src = "server" if h else "in-process"
    quiet = args.json or args.stats or args.resolve
    if h and not quiet:
        print(f"（服务 {S.server_url(args.port)}  页面 {h.get('pages')}）", file=sys.stderr)
    if (not h) and (not args.no_server) and args.mode in ("semantic", "hybrid") \
            and not quiet:
        print("[!] 常驻服务未运行 → 进程内执行，语义/混合模式将需 30–56 秒。"
              "建议先启动： python tools/kb_serve.py --warm", file=sys.stderr)

    t0 = time.time()
    if args.stats:
        data, src = call("/stats", args.port, _fallback_stats)
    elif args.route or args.corpus:
        if not args.query:
            ap.error("--route / --corpus 需要查询词")
        q = args.query
        if args.route:
            path = (f"/route?q={urllib.parse.quote(q)}"
                    f"&budget={args.budget}&layer={args.layer}")
            fb = lambda: _fallback_route(q, args.budget, args.layer)   # noqa: E731
        else:
            path = f"/corpus?q={urllib.parse.quote(q)}&k={args.k}"
            fb = lambda: _fallback_corpus(q, args.k)                   # noqa: E731
        data, src = call(path, args.port, fb)
    elif args.resolve:
        if not args.query:
            ap.error("--resolve 需要查询词")
        q = args.query
        data, src = call(f"/resolve?q={urllib.parse.quote(q)}", args.port,
                         lambda: _fallback_resolve(q))
        data["source"] = src
        if args.json:
            print(json.dumps(data, ensure_ascii=False, indent=1))
        else:
            hits = data.get("alias_hits") or []
            print("（无别名命中）" if not hits else
                  "\n".join(f"  {a}  ->  {c}" for a, c in hits))
        return 0
    else:
        if not args.query:
            ap.print_help()
            return 1
        q = args.query
        types = [t.strip() for t in args.type.split(",") if t.strip()]
        path = (f"/search?q={urllib.parse.quote(q)}&k={args.k}"
                f"&mode={args.mode}&type={','.join(types)}")
        data, src = call(path, args.port,
                         lambda: _fallback_search(q, args.k, types, args.mode))
    dt = (time.time() - t0) * 1000

    data["source"] = src
    data["elapsed_ms"] = round(dt, 1)

    if args.json:
        print(json.dumps(data, ensure_ascii=False, indent=1))
        return 0

    if args.stats:
        print(f"页面总数 : {data.get('pages')}")
        print(f"别名条目 : {data.get('alias_entries')}")
        print(f"词表大小 : {data.get('vocab')}")
        print(f"BM25 版本: v{data.get('bm25_version')}")
        print(f"来源     : {src}   {dt:.1f} ms")
        return 0

    if args.route:
        print("=" * 70)
        print(f'  上下文包  "{q}"   （来源 {src}, {dt:.1f} ms）')
        print("=" * 70)
        sig = data.get("signal") or {}
        if sig.get("low_confidence"):
            print("⚠️ 各层最高分都偏低 —— 该查询在库内可能没有强命中。")
        for lv, title in (("L1", "L1 综合层（定义/机制/共识）"),
                          ("L2", "L2 文献卡层（单篇主张/可靠性）"),
                          ("L3", "L3 原文层（可回指 raw 行号）")):
            items = data.get(lv) or []
            if not items:
                continue
            print(f"\n— {title} —")
            for x in items:
                head = x.get("citation") or x.get("name") or x.get("path")
                print(f"  {head}   ({x.get('score')})")
                if x.get("source_reliability"):
                    print(f"      可靠性: {x['source_reliability'][:120]}")
                elif x.get("summary"):
                    print(f"      {x['summary'][:140]}")
                if x.get("snippet"):
                    print(f"      {x['snippet'][:140]}...")
        if data.get("suggested_read"):
            print("\n建议阅读集：")
            for p in data["suggested_read"]:
                print(f"  {p}")
        return 0

    if args.corpus:
        print(f'语料检索: "{q}"   命中 {data.get("count")} 块'
              f'   （来源 {src}, {dt:.1f} ms）\n')
        for i, r in enumerate(data.get("results", []), 1):
            print(f'{i:>2}. [{r["score"]}] {r["path"]}:{r["line_start"]}-{r["line_end"]}')
            if r.get("heading"):
                print(f'    § {r["heading"]}')
            if r.get("source_page"):
                bits = [f'来源页 [[sources/{r["source_page"]}]]']
                if r.get("source_reliability"):
                    bits.append(f'可靠性={r["source_reliability"][:60]}')
                print("    " + "  ".join(bits))
            print(f'    {(r.get("snippet") or "")[:180]}...')
            print()
        return 0

    print(f'[{data.get("mode")}] 查询: "{q}"   命中 {data.get("count")} 条'
          f'   （来源 {src}, {dt:.1f} ms）\n')
    for i, it in enumerate(data.get("results", []), 1):
        print(f'{i:>2}. [{it["type"]}] {it["name"]}   ({it["score"]}, 更新 {it["updated"]})')
        if it.get("summary"):
            s = it["summary"]
            print(f'    {s[:150]}{"..." if len(s) > 150 else ""}')
        if it.get("aliases"):
            print(f'    别名: {", ".join(it["aliases"][:6])}')
        if it.get("path"):
            print(f'    路径: {it["path"]}')
    return 0


def doctor(port):
    print("=== kb.py --doctor ===")
    ok = True
    print(f"库根: {K.VAULT}")
    for p, label in ((K.META_PATH, "meta.json"), (K.BM25_PATH, "bm25.json"),
                     (K.META_LITE_PATH, "meta_lite.json"),
                     (K.FULL_PATH, "meta_full.json")):
        ex = os.path.exists(p)
        sz = f"{os.path.getsize(p)/1024:.0f} KB" if ex else "-"
        print(f"  [{'ok' if ex else 'MISS'}] {label:<16} {sz}")
        ok = ok and ex
    try:
        import kb_search as KS
        meta, bm = KS.load_index()
        print(f"  索引版本: bm25 v{bm.get('_version', 1)}  "
              f"页面 {meta.get('count')}  词表 {len(bm.get('df', {}))}")
    except Exception as e:                       # noqa: BLE001
        print(f"  [FAIL] 索引不可加载: {e}")
        ok = False
    try:
        import kb_semantic_search as SEM
        em, emap = SEM._load_embeddings()
        if em is None:
            print("  [MISS] 嵌入索引不存在")
        else:
            missing, stale, fresh = SEM.check_index_freshness(emap, verbose=False)
            print(f"  [{'ok' if fresh else 'FAIL'}] 嵌入索引 {len(emap)} 页, "
                  f"缺失 {len(missing)}, 幽灵 {len(stale)}")
            ok = ok and fresh
    except Exception as e:                       # noqa: BLE001
        print(f"  [!] 语义模块: {e}")
    h = S.ping(port)
    if h:
        print(f"  [ok] 常驻服务 {S.server_url(port)}  pid={h['pid']}  "
              f"语义预热={h['semantic'].get('warm')}")
    else:
        print(f"  [--] 常驻服务未运行（{S.server_url(port)}）"
              f" → 建议： python tools/kb_serve.py --warm")
    print("=== doctor", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


